  function moneyBOB(n){return new Intl.NumberFormat("es-BO",{style:"currency",currency:"BOB",minimumFractionDigits:2,maximumFractionDigits:2}).format(Number.isFinite(n)?n:0).replace("BOB","Bs");}
  const currencyNames={BOB:"Bolivianos (Bs)",USD:"Dólares estadounidenses (USD)",EUR:"Euros (EUR)",BRL:"Reales brasileños (BRL)",ARS:"Pesos argentinos (ARS)",CLP:"Pesos chilenos (CLP)",PEN:"Soles peruanos (PEN)",GBP:"Libras esterlinas (GBP)",JPY:"Yenes japoneses (JPY)"};
  function currencyUnit(){return currencyCode==="BOB"?"Bs":currencyCode;}
  function updateCurrency(code){const next=String(code||"BOB").toUpperCase(),changed=next!==currencyCode;currencyCode=next;localStorage.setItem("fieDemoCurrency",currencyCode);["planCurrency","capacityCurrency"].forEach(id=>{const select=$(id);if(!select)return;if(!Array.from(select.options).some(o=>o.value===currencyCode)){const opt=document.createElement("option");opt.value=currencyCode;opt.textContent=`Otra moneda (${currencyCode})`;select.appendChild(opt);}select.value=currencyCode;});document.querySelectorAll("[data-currency-unit]").forEach(el=>el.textContent=currencyUnit());document.querySelectorAll(".currency-tile").forEach(el=>el.classList.toggle("active",el.dataset.currency===currencyCode));const current=$("currencyCurrentLabel");if(current)current.textContent=`Moneda seleccionada: ${currencyUnit()} · ${currencyCode}`;const hero=document.querySelector(".hero-card .hero-stat strong");if(hero)hero.textContent=currencyNames[currencyCode]||currencyCode;const note=document.querySelector(".micro-note");if(note)note.textContent=`Herramientas de cálculo para operaciones crediticias en ${currencyNames[currencyCode]||currencyCode}.`;if(changed){const treField=$("treRate");if(treField)treField.value=$("rateMode")?.value==="variable"?(currencyCode==="BOB"?"3.78":currencyCode==="USD"?"0.50":"0"):"0";if($("planResults"))$("planResults").classList.add("hidden");if($("capacityResults"))$("capacityResults").classList.add("hidden");latestPlan=null;latestCapacity=null;}if(businessRatesReady&&$("businessRateReference"))updateBusinessRate();}
  ["planCurrency","capacityCurrency"].forEach(id=>$(id)?.addEventListener("change",e=>updateCurrency(e.target.value)));
