  function setAuthenticated(value){ authenticated=value; $("adminBadge").classList.toggle("hidden",!value); $("logoutBtn").classList.toggle("hidden",!value); $("headerLogin").classList.toggle("hidden",value); $("mainNav").classList.toggle("admin-nav",value); document.body.classList.toggle("is-admin",value); }
