  function getPurpose(prefix){const select=$(prefix+"Purpose");return select.value==="__other__"?$(prefix+"PurposeOther").value.trim():select.value.trim();}
  function updatePurposeOther(prefix){const other=$(prefix+"Purpose").value==="__other__";$(prefix+"PurposeOtherWrap").classList.toggle("hidden",!other);$(prefix+"PurposeOther").required=other;if(!other)$(prefix+"PurposeOther").value="";}
  ["plan","capacity"].forEach(prefix=>{$(prefix+"Purpose").addEventListener("change",()=>updatePurposeOther(prefix));updatePurposeOther(prefix);});
  function setPurpose(prefix,purpose){const select=$(prefix+"Purpose"),match=Array.from(select.options).find(o=>o.value===purpose);if(match){select.value=purpose;$(prefix+"PurposeOther").value="";}else{select.value="__other__";$(prefix+"PurposeOther").value=purpose;}updatePurposeOther(prefix);}
  function inferPurposeCategory(purpose){
    const p=String(purpose||"");
    const candidates=[
      ["Crédito educativo",purposeRules.educativo],["Crédito de vivienda",purposeRules.vivienda],["Crédito vehicular",purposeRules.vehicular],["Crédito agropecuario",purposeRules.agropecuario],["Crédito de consumo",purposeRules.consumo],["Capital de operaciones / trabajo",purposeRules.capital_trabajo],["Crédito de inversión productiva",purposeRules.inversion],["Financiamiento productivo",purposeRules.productivo],["Crédito para microempresa o negocio",purposeRules.microcredito],["Crédito PyME o empresarial",purposeRules.pyme]
    ];
    return candidates.find(([label,rule])=>rule.test(p))?.[0]||"No se pudo determinar con suficiente precisión; revisa el destino declarado";
  }
  function validateCreditPurpose(type,purpose){
    const clean=String(purpose||"").trim();
    if(clean.length<5) return {ok:false,message:"Describe con mayor claridad para qué necesitas el crédito (mínimo 5 caracteres)."};
    const rule=purposeRules[type];
    if(!rule || !rule.test(clean)){const inferred=inferPurposeCategory(clean);return {ok:false,message:`La finalidad indicada no parece corresponder al tipo de crédito seleccionado.\n\nTIPO DE CRÉDITO SELECCIONADO: ${creditLabels[type]||type}.\nFINALIDAD INGRESADA: ${clean}.\n\nRevisa el tipo de crédito seleccionado o modifica la finalidad para que ambos datos sean coherentes.\n\nCLASIFICACIÓN ORIENTATIVA DEL MOTIVO: ${inferred}.

El motivo que ingresaste corresponde orientativamente a: ${inferred}. Selecciona ese tipo de crédito o corrige el motivo para continuar.`};}
    return {ok:true};
  }
