  $("validationModal").addEventListener("click",e=>{if(e.target===$("validationModal"))$("validationModal").classList.add("hidden");});
  function validatePurposeFor(prefix){const type=$(prefix+"CreditType").value,purpose=getPurpose(prefix),result=validateCreditPurpose(type,purpose);if(!result.ok){showValidation(result.message);$(prefix+( $(prefix+"Purpose").value==="__other__"?"PurposeOther":"Purpose")).focus();return false;}return true;}

