    $("planDictamen").innerHTML=`<h3>Informe técnico del plan de pagos</h3><p class="dictamen-lead">${safeText(planLead)}</p><div class="dictamen-grid">${planItems.map(([k,v])=>`<div class="dictamen-item"><b>${safeText(k)}</b><p>${safeText(v)}</p></div>`).join("")}</div><small>Fecha de emisión: ${new Date().toLocaleDateString("es-BO")} · Valores estimados en ${safeText(currencyNames[result.input.currency]||result.input.currency)}.</small>`;
