  function scenarioChartPng(scenarios){
    const canvas=document.createElement("canvas");canvas.width=1100;canvas.height=420;const ctx=canvas.getContext("2d");
    ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#2d4b9b";ctx.font="bold 26px Arial";ctx.fillText("COMPARACIÓN DE ESCENARIOS",38,44);ctx.font="16px Arial";ctx.fillStyle="#6b6572";ctx.fillText(`Margen mensual después de la nueva cuota · ${currencyCode}`,38,72);
    const max=Math.max(1,...scenarios.map(sc=>Math.abs(sc.margin)));const axis=550,barMax=420,colors={favorable:"#4b8e70",base:"#2d4b9b",adverse:"#b33b45"};ctx.strokeStyle="#aaa5b2";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(axis,105);ctx.lineTo(axis,370);ctx.stroke();
    scenarios.forEach((sc,i)=>{const y=135+i*88,w=Math.max(3,Math.abs(sc.margin)/max*barMax);ctx.font="bold 18px Arial";ctx.fillStyle="#34303a";ctx.textAlign="left";ctx.fillText(sc.label,38,y+8);ctx.fillStyle=colors[sc.key]||"#2d4b9b";ctx.fillRect(sc.margin>=0?axis:axis-w,y+18,w,28);ctx.font="bold 17px Arial";ctx.fillStyle="#34303a";ctx.textAlign=sc.margin>=0?"left":"right";ctx.fillText(money(sc.margin),sc.margin>=0?axis+w+12:axis-w-12,y+39);});
    return canvas.toDataURL("image/png");
  }
