    const collateralRatio=r.fiveCLoanAmount>0?r.fiveCCollateralValue/r.fiveCLoanAmount:null;
    const collateralScore=r.fiveCCollateral==="none"?0:(collateralRatio>=1?2:collateralRatio>=0.5?1:0);
    const conditionsScore=r.fiveCConditions.length>=40?2:r.fiveCConditions.length>=12?1:0;
