    const items=[...fiveCItems,["Tipo de crédito y finalidad",`${creditLabels[r.creditType]} · ${r.purpose}`],["Moneda de simulación",`${currencyNames[r.currency]||r.currency} (${r.currency})`],["Perfil evaluado",r.profile==="business"?`Negocio / empresa · ${r.businessSizeLabel} · ${r.businessSector==="productive"?"Productivo y agropecuario":"Comercio y servicios"}`:"Persona o familia"],["Base de ingresos y gastos",`${money(r.income)} de ingreso/flujo neto; ${methodExpense}`],["Capacidad mensual",`Disponible antes de la nueva cuota: ${money(r.available)}. Margen posterior a la nueva cuota: ${money(r.margin)}.`],["Endeudamiento DTI",r.allDebtRatio===null?"No calculable por falta de base de ingreso positiva.":`${number(r.allDebtRatio)}% frente al límite configurado de ${number(r.paymentLimit)}%.`],["Cobertura DSCR",r.dscr===null?"No calculable porque no existe servicio mensual de deuda positivo.":`${number(r.dscr)} veces frente al mínimo configurado de ${number(r.minDscr)} veces.`],["Escenarios comparativos",r.scenarios.map(sc=>`${sc.label}: margen ${money(sc.margin)}, DTI ${sc.dti===null?"N/C":number(sc.dti)+"%"}, DSCR ${sc.dscr===null?"N/C":number(sc.dscr)+"x"}. ${sc.assumption}.`).join(" | ")],["Cuota máxima orientativa",money(r.maximum)],["Referencia de tasa",rateDetail],["Parámetros y alcance","El resultado se genera con los valores ingresados y los umbrales configurables del simulador; no reemplaza la revisión documental, clasificación oficial de la unidad productiva ni evaluación integral de riesgo."]];
