      ...r.scenarios.map(sc=>[sc.label,money(sc.margin),`${sc.assumption}. DTI: ${sc.dti===null?"N/C":number(sc.dti)+"%"}; DSCR: ${sc.dscr===null?"N/C":number(sc.dscr)+" veces"}. ${sc.interpretation}`]),
