  $("capacityForm").addEventListener("submit",e=>{e.preventDefault();if(!validatePurposeFor("capacity"))return;const business=$("profile").value==="business";if(business&&businessCreditTypes.includes($("capacityCreditType").value)&&$("businessSizeMethod").value==="guided"&&!classifyBusinessByBolivianIndex().valid){$("capacityError").textContent="Completa ventas anuales, patrimonio neto y número de trabajadores mayores que cero para clasificar la empresa mediante el índice boliviano.";$("businessAnnualSales").focus();return;}if(!business&&!$("expenseMode").value){$("capacityError").textContent="Selecciona primero cómo deseas registrar los gastos.";$("expenseMode").focus();return;}const ids=business?["businessSales","costOfSales","operatingCosts","businessTaxes","ownerWithdrawals","otherCashOutflows","businessAnnualSales","businessEmployees","businessNetWorth","fiveCLoanAmount","fiveCStability","fiveCNetWorth","fiveCOwnContribution","fiveCCollateralValue","existingDebts","proposedPayment","incomeDrop","expenseRise","safetyMargin","paymentLimit","minDscr"]:["income","existingDebts","proposedPayment","fiveCLoanAmount","fiveCStability","fiveCNetWorth","fiveCOwnContribution","fiveCCollateralValue","incomeDrop","expenseRise","safetyMargin","paymentLimit","minDscr",...($("expenseMode").value==="percentage"?["expensePercent"]:[]),...($("expenseMode").value==="detail"?["foodExpense","housingExpense","utilitiesExpense","educationExpense","transportExpense","otherPersonalExpense"]:[])];if(!validNonNegative(ids,$("capacityError")))return;if(business&&!Number.isInteger(val("businessEmployees"))){$("capacityError").textContent="El número de trabajadores debe ser un número entero.";$("businessEmployees").focus();return;}const x=readCapacity();if(x.incomeDrop>100||x.expenseRise>300||x.safetyMargin>90||x.paymentLimit>100||x.expensePercent>100||x.minDscr<=0||x.minDscr>20){$("capacityError").textContent="Uno o más porcentajes superan el rango permitido.";return;}renderCapacity(computeCapacity(x));});
  $("capacityReset").addEventListener("click",()=>{$("capacityForm").reset();$("capacityCurrency").value=currencyCode;updateCurrency(currencyCode);updatePurposeOther("capacity");$("capacityLabel").value="";$("income").value=5000;$("expensePercent").value=50;$("businessSales").value=30000;$("costOfSales").value=15000;$("operatingCosts").value=7000;$("businessTaxes").value=0;$("ownerWithdrawals").value=0;$("otherCashOutflows").value=0;$("existingDebts").value=500;$("proposedPayment").value=800;$("incomeDrop").value=10;$("expenseRise").value=10;$("safetyMargin").value=10;$("paymentLimit").value=settings.limit;$("minDscr").value=1.25;$("expenseMode").value="";$("capacityError").textContent="";$("capacityResults").classList.add("hidden");latestCapacity=null;updateProfileFields();updateExpenseMode();updateBusinessRate();});
