  function renderSaved(){
    const list=loadJSON(savedKey,[]),host=$("savedList");
    if(!list.length){host.innerHTML='<div class="empty-state"><strong>No hay simulaciones guardadas todavía</strong>Calcula un plan de pagos o un análisis de capacidad y usa “Guardar para comparar”.</div>';return;}
    host.innerHTML=list.map(item=>`<article class="saved-item"><div><strong>${safeText(item.label||"Simulación")}</strong><p>${safeText(item.type==="plan"?"Plan de pagos":"Capacidad de pagos")} · ${safeText(item.summary||"")} · ${new Date(item.savedAt).toLocaleString("es-BO")}</p></div><div class="saved-actions"><button class="btn secondary" data-open-saved="${item.id}">Ver datos</button><button class="btn danger-outline" data-delete-saved="${item.id}">Eliminar</button></div></article>`).join("");
    host.querySelectorAll("[data-delete-saved]").forEach(b=>b.addEventListener("click",()=>{localStorage.setItem(savedKey,JSON.stringify(loadJSON(savedKey,[]).filter(x=>x.id!==Number(b.dataset.deleteSaved))));renderSaved();toast("Simulación eliminada.");}));
    host.querySelectorAll("[data-open-saved]").forEach(b=>b.addEventListener("click",()=>{const item=loadJSON(savedKey,[]).find(x=>x.id===Number(b.dataset.openSaved));if(!item)return;if(item.type==="plan"){renderPlan(item.data);go("plan");}else{renderCapacity(item.data);go("capacity");}}));
  }
  $("clearSaved").addEventListener("click",()=>{if(confirm("¿Borrar todas las simulaciones guardadas en este navegador?")){localStorage.removeItem(savedKey);renderSaved();toast("Historial borrado.");}});
  function fillSettings(){settings={...defaults,...settings};$("defaultRate").value=settings.rate;$("defaultLimit").value=settings.limit;$("defaultDesgravamen").value=settings.desgravamen;$("defaultCesantia").value=settings.cesantia;$("defaultOtherInsurance").value=settings.otherInsurance;$("parameterYear").value=settings.year;$("parameterName").value=settings.name;$("parameterSource").value=settings.source;}
  function applyInsuranceDefaults(){if($("desgravamenRate"))$("desgravamenRate").value=settings.desgravamen;if($("cesantiaRate"))$("cesantiaRate").value=settings.cesantia;if($("otherInsurance"))$("otherInsurance").value=settings.otherInsurance;}
  $("settingsForm").addEventListener("submit",e=>{e.preventDefault();const rate=val("defaultRate"),limit=val("defaultLimit"),desgravamen=val("defaultDesgravamen"),cesantia=val("defaultCesantia"),otherInsurance=val("defaultOtherInsurance"),year=val("parameterYear");if(!Number.isFinite(rate)||rate<0||rate>200||!Number.isFinite(limit)||limit<1||limit>100||!Number.isFinite(desgravamen)||desgravamen<0||desgravamen>100||!Number.isFinite(cesantia)||cesantia<0||cesantia>100||!Number.isFinite(otherInsurance)||otherInsurance<0||!Number.isInteger(year)||year<2020||year>2100){$("settingsMessage").textContent="Revisa los valores permitidos de tasas, seguros y año.";return;}settings={rate,limit,desgravamen,cesantia,otherInsurance,year,name:$("parameterName").value.trim()||"Parámetros personalizados",source:$("parameterSource").value.trim()||"Sin fuente indicada; tratar como valor de prueba."};localStorage.setItem(settingsKey,JSON.stringify(settings));applyInsuranceDefaults();$("annualRate").value=settings.rate;$("paymentLimit").value=settings.limit;$("settingsMessage").textContent=`Parámetros ${year} guardados en este navegador y aplicados al plan de pagos.`;toast("Configuración guardada y aplicada.");});
  $("resetSettings").addEventListener("click",()=>{settings={...defaults};localStorage.setItem(settingsKey,JSON.stringify(settings));fillSettings();applyInsuranceDefaults();$("annualRate").value=settings.rate;$("paymentLimit").value=settings.limit;$("settingsMessage").textContent="Se restauraron los valores iniciales de 2026.";});
  fillSettings();applyInsuranceDefaults();if($("annualRate"))$("annualRate").value=settings.rate;if($("paymentLimit"))$("paymentLimit").value=settings.limit;
